(1, 2, 4, 2, 'Что такое AJAX?', 'Сейчас в сети Интернет наблюдается очень активное развитие (и даже использование) новых технологий. Одна из таких технологий — AJAX.', '6585cd83c81845c04b3202dd193f0433', 'gif', '{\"time\":1642775026856,\"blocks\":[{\"id\":\"N1DHiYjuu2\",\"type\":\"paragraph\",\"data\":{\"text\":\"AJAX \\u2014 \\u044d\\u0442\\u043e \\u0430\\u0431\\u0431\\u0440\\u0435\\u0432\\u0438\\u0430\\u0442\\u0443\\u0440\\u0430, \\u043a\\u043e\\u0442\\u043e\\u0440\\u0430\\u044f \\u043e\\u0437\\u043d\\u0430\\u0447\\u0430\\u0435\\u0442 Asynchronous Javascript and XML. \\u041d\\u0430 \\u0441\\u0430\\u043c\\u043e\\u043c \\u0434\\u0435\\u043b\\u0435, AJAX \\u043d\\u0435 \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043d\\u043e\\u0432\\u043e\\u0439 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0435\\u0439, \\u0442\\u0430\\u043a \\u043a\\u0430\\u043a \\u0438 Javascript, \\u0438 XML \\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442 \\u0443\\u0436\\u0435 \\u0434\\u043e\\u0432\\u043e\\u043b\\u044c\\u043d\\u043e \\u043f\\u0440\\u043e\\u0434\\u043e\\u043b\\u0436\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f, \\u0430 AJAX \\u2014 \\u044d\\u0442\\u043e \\u0441\\u0438\\u043d\\u0442\\u0435\\u0437 \\u043e\\u0431\\u043e\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0439. AJAX \\u0447\\u0430\\u0449\\u0435 \\u0432\\u0441\\u0435\\u0433\\u043e \\u0430\\u0441\\u0441\\u043e\\u0446\\u0438\\u0440\\u0438\\u0443\\u0435\\u0442\\u0441\\u044f \\u0441 \\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u043e\\u043c Web 2.0 \\u0438 \\u043f\\u0440\\u0435\\u043f\\u043e\\u0434\\u043d\\u043e\\u0441\\u0438\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u043d\\u043e\\u0432\\u0435\\u0439\\u0448\\u0435\\u0435 Web-\\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435.\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"kTntxToBuy\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\u041f\\u0440\\u0438 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0438 AJAX \\u043d\\u0435\\u0442 \\u043d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0442\\u044c \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0440\\u0430\\u0437 \\u0432\\u0441\\u044e \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u0443, \\u0442\\u0430\\u043a \\u043a\\u0430\\u043a \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0435\\u0435 \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u0430\\u044f \\u0447\\u0430\\u0441\\u0442\\u044c. \\u042d\\u0442\\u043e \\u043d\\u0430\\u043c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0434\\u043e\\u0431\\u043d\\u0435\\u0435, \\u0442\\u0430\\u043a \\u043a\\u0430\\u043a \\u043d\\u0435 \\u043f\\u0440\\u0438\\u0445\\u043e\\u0434\\u0438\\u0442\\u0441\\u044f \\u0434\\u043e\\u043b\\u0433\\u043e \\u0436\\u0434\\u0430\\u0442\\u044c, \\u0438 \\u044d\\u043a\\u043e\\u043d\\u043e\\u043c\\u0438\\u0447\\u043d\\u0435\\u0435, \\u0442\\u0430\\u043a \\u043a\\u0430\\u043a \\u043d\\u0435 \\u0432\\u0441\\u0435 \\u043e\\u0431\\u043b\\u0430\\u0434\\u0430\\u044e\\u0442 \\u0431\\u0435\\u0437\\u043b\\u0438\\u043c\\u0438\\u0442\\u043d\\u044b\\u043c \\u0438\\u043d\\u0442\\u0435\\u0440\\u043d\\u0435\\u0442\\u043e\\u043c. \\u041f\\u0440\\u0430\\u0432\\u0434\\u0430 \\u0432 \\u044d\\u0442\\u043e\\u043c \\u0441\\u043b\\u0443\\u0447\\u0430\\u0435, \\u0440\\u0430\\u0437\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a\\u0443 \\u043d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e \\u0441\\u043b\\u0435\\u0434\\u0438\\u0442\\u044c, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c \\u0431\\u044b\\u043b \\u0432 \\u043a\\u0443\\u0440\\u0441\\u0435 \\u0442\\u043e\\u0433\\u043e, \\u0447\\u0442\\u043e \\u043f\\u0440\\u043e\\u0438\\u0441\\u0445\\u043e\\u0434\\u0438\\u0442 \\u043d\\u0430 \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u0435. \\u042d\\u0442\\u043e \\u043c\\u043e\\u0436\\u043d\\u043e \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u043e\\u0432\\u0430\\u0442\\u044c \\u0441 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c \\u0438\\u043d\\u0434\\u0438\\u043a\\u0430\\u0442\\u043e\\u0440\\u043e\\u0432 \\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0438, \\u0442\\u0435\\u043a\\u0441\\u0442\\u043e\\u0432\\u044b\\u0445 \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u0439 \\u043e \\u0442\\u043e\\u043c, \\u0447\\u0442\\u043e \\u0438\\u0434\\u0451\\u0442 \\u043e\\u0431\\u043c\\u0435\\u043d \\u0434\\u0430\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0441 \\u0441\\u0435\\u0440\\u0432\\u0435\\u0440\\u043e\\u043c. \\u041d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e \\u0442\\u0430\\u043a\\u0436\\u0435 \\u043f\\u043e\\u043d\\u0438\\u043c\\u0430\\u0442\\u044c, \\u0447\\u0442\\u043e \\u043d\\u0435 \\u0432\\u0441\\u0435 \\u0431\\u0440\\u0430\\u0443\\u0437\\u0435\\u0440\\u044b \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u0438\\u0432\\u0430\\u044e\\u0442 AJAX (\\u0441\\u0442\\u0430\\u0440\\u044b\\u0435 \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 \\u0431\\u0440\\u0430\\u0443\\u0437\\u0435\\u0440\\u043e\\u0432 \\u0438 \\u0442\\u0435\\u043a\\u0441\\u0442\\u043e\\u0432\\u044b\\u0435 \\u0431\\u0440\\u0430\\u0443\\u0437\\u0435\\u0440\\u044b). \\u041f\\u043b\\u044e\\u0441 Javascript \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0431\\u044b\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u043c. \\u041f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443, \\u043d\\u0435 \\u0441\\u043b\\u0435\\u0434\\u0443\\u0435\\u0442 \\u0437\\u043b\\u043e\\u0443\\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u043b\\u044f\\u0442\\u044c \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0438 \\u0438 \\u043f\\u0440\\u0438\\u0431\\u0435\\u0433\\u0430\\u0442\\u044c \\u043a \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u043c \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430\\u043c \\u043f\\u0440\\u0435\\u0434\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u0438 \\u043d\\u0430 Web-\\u0441\\u0430\\u0439\\u0442\\u0435.\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"HQGIwEiEvn\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\u041e\\u0431\\u043e\\u0431\\u0449\\u0438\\u043c \\u0434\\u043e\\u0441\\u0442\\u043e\\u0438\\u043d\\u0441\\u0442\\u0432\\u0430 AJAX:\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"w3RetRmbCf\",\"type\":\"list\",\"data\":{\"style\":\"ordered\",\"items\":[{\"content\":\"\\u0412\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u044f \\u0443\\u0434\\u043e\\u0431\\u043d\\u043e\\u0433\\u043e Web-\\u0438\\u043d\\u0442\\u0435\\u0440\\u0444\\u0435\\u0439\\u0441\\u0430\",\"items\":[]},{\"content\":\"\\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0435 \\u0432\\u0437\\u0430\\u0438\\u043c\\u043e\\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0435 \\u0441 \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u043c\",\"items\":[]},{\"content\":\"\\u0427\\u0430\\u0441\\u0442\\u0438\\u0447\\u043d\\u0430\\u044f \\u043f\\u0435\\u0440\\u0435\\u0437\\u0430\\u0433\\u0440\\u0443\\u0437\\u043a\\u0430 \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u044b, \\u0432\\u043c\\u0435\\u0441\\u0442\\u043e \\u043f\\u043e\\u043b\\u043d\\u043e\\u0439\",\"items\":[]},{\"content\":\"\\u0423\\u0434\\u043e\\u0431\\u0441