0432\\u043e\\u0434 \\u0442\\u0435\\u043a\\u0441\\u0442\\u0430 \\\"\\u041f\\u0440\\u0438\\u0432\\u0435\\u0442, \\u044f - \\u0441\\u043a\\u0440\\u0438\\u043f\\u0442 PHP!\\\"). \\u041a\\u043e\\u0434 PHP \\u043e\\u0442\\u0434\\u0435\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c\\u0438&nbsp;\\u043d\\u0430\\u0447\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c \\u0438 \\u043a\\u043e\\u043d\\u0435\\u0447\\u043d\\u044b\\u043c \\u0442\\u0435\\u0433\\u0430\\u043c\\u0438&nbsp;&lt;?php&nbsp;\\u0438&nbsp;?&gt;, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u044e\\u0442 \\\"\\u043f\\u0435\\u0440\\u0435\\u043a\\u043b\\u044e\\u0447\\u0430\\u0442\\u044c\\u0441\\u044f\\\" \\u0432 \\\"PHP-\\u0440\\u0435\\u0436\\u0438\\u043c\\\" \\u0438 \\u0432\\u044b\\u0445\\u043e\\u0434\\u0438\\u0442\\u044c \\u0438\\u0437 \\u043d\\u0435\\u0433\\u043e.&nbsp;&nbsp;\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"O2ONjD_K5g\",\"type\":\"paragraph\",\"data\":{\"text\":\"PHP \\u043e\\u0442\\u043b\\u0438\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u043e\\u0442 JavaScript \\u0442\\u0435\\u043c, \\u0447\\u0442\\u043e PHP-\\u0441\\u043a\\u0440\\u0438\\u043f\\u0442\\u044b \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u044f\\u044e\\u0442\\u0441\\u044f \\u043d\\u0430 \\u0441\\u0435\\u0440\\u0432\\u0435\\u0440\\u0435 \\u0438 \\u0433\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u0443\\u044e\\u0442 HTML, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0439 \\u043f\\u043e\\u0441\\u044b\\u043b\\u0430\\u0435\\u0442\\u0441\\u044f \\u043a\\u043b\\u0438\\u0435\\u043d\\u0442\\u0443. \\u0415\\u0441\\u043b\\u0438 \\u0431\\u044b \\u0443 \\u0432\\u0430\\u0441 \\u043d\\u0430 \\u0441\\u0435\\u0440\\u0432\\u0435\\u0440\\u0435 \\u0431\\u044b\\u043b \\u0440\\u0430\\u0437\\u043c\\u0435\\u0449\\u0451\\u043d \\u0441\\u043a\\u0440\\u0438\\u043f\\u0442, \\u043f\\u043e\\u0434\\u043e\\u0431\\u043d\\u044b\\u0439 \\u0432\\u044b\\u0448\\u0435\\u043f\\u0440\\u0438\\u0432\\u0435\\u0434\\u0451\\u043d\\u043d\\u043e\\u043c\\u0443, \\u043a\\u043b\\u0438\\u0435\\u043d\\u0442 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0438\\u043b \\u0431\\u044b \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u0435\\u0433\\u043e \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f, \\u043d\\u043e \\u043d\\u0435 \\u0441\\u043c\\u043e\\u0433 \\u0431\\u044b \\u0432\\u044b\\u044f\\u0441\\u043d\\u0438\\u0442\\u044c, \\u043a\\u0430\\u043a\\u043e\\u0439 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u043a\\u043e\\u0434 \\u0435\\u0433\\u043e \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u0451\\u043b. \\u0412\\u044b \\u0434\\u0430\\u0436\\u0435 \\u043c\\u043e\\u0436\\u0435\\u0442\\u0435 \\u043d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0438\\u0442\\u044c \\u0441\\u0432\\u043e\\u0439 \\u0441\\u0435\\u0440\\u0432\\u0435\\u0440 \\u0442\\u0430\\u043a\\u0438\\u043c \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u043c, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043e\\u0431\\u044b\\u0447\\u043d\\u044b\\u0435 HTML-\\u0444\\u0430\\u0439\\u043b\\u044b \\u043e\\u0431\\u0440\\u0430\\u0431\\u0430\\u0442\\u044b\\u0432\\u0430\\u043b\\u0438\\u0441\\u044c \\u043f\\u0440\\u043e\\u0446\\u0435\\u0441\\u0441\\u043e\\u0440\\u043e\\u043c PHP, \\u0442\\u0430\\u043a \\u0447\\u0442\\u043e \\u043a\\u043b\\u0438\\u0435\\u043d\\u0442\\u044b \\u0434\\u0430\\u0436\\u0435 \\u043d\\u0435 \\u0441\\u043c\\u043e\\u0433\\u0443\\u0442 \\u0443\\u0437\\u043d\\u0430\\u0442\\u044c, \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u044e\\u0442 \\u043b\\u0438 \\u043e\\u043d\\u0438 \\u043e\\u0431\\u044b\\u0447\\u043d\\u044b\\u0439 HTML-\\u0444\\u0430\\u0439\\u043b \\u0438\\u043b\\u0438 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u0441\\u043a\\u0440\\u0438\\u043f\\u0442\\u0430.\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"of9hSPwl_l\",\"type\":\"paragraph\",\"data\":{\"text\":\"PHP \\u043a\\u0440\\u0430\\u0439\\u043d\\u0435 \\u043f\\u0440\\u043e\\u0441\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0441\\u0432\\u043e\\u0435\\u043d\\u0438\\u044f, \\u043d\\u043e \\u0432\\u043c\\u0435\\u0441\\u0442\\u0435 \\u0441 \\u0442\\u0435\\u043c \\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u0435\\u043d \\u0443\\u0434\\u043e\\u0432\\u043b\\u0435\\u0442\\u0432\\u043e\\u0440\\u0438\\u0442\\u044c \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u044b \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c\\u0438\\u0441\\u0442\\u043e\\u0432. \\u041d\\u0435 \\u043f\\u0443\\u0433\\u0430\\u0439\\u0442\\u0435\\u0441\\u044c \\u0434\\u043b\\u0438\\u043d\\u043d\\u043e\\u0433\\u043e \\u0441\\u043f\\u0438\\u0441\\u043a\\u0430 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 PHP. \\u0412\\u044b \\u043c\\u043e\\u0436\\u0435\\u0442\\u0435 \\u0431\\u044b\\u0441\\u0442\\u0440\\u043e \\u043d\\u0430\\u0447\\u0430\\u0442\\u044c, \\u0438 \\u0443\\u0436\\u0435 \\u0432 \\u0442\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u0438\\u0445 \\u0447\\u0430\\u0441\\u043e\\u0432 \\u0441\\u043c\\u043e\\u0436\\u0435\\u0442\\u0435 \\u0441\\u043e\\u0437\\u0434\\u0430\\u0432\\u0430\\u0442\\u044c \\u043f\\u0440\\u043e\\u0441\\u0442\\u044b\\u0435 PHP-\\u0441\\u043a\\u0440\\u0438\\u043f\\u0442\\u044b.\"},\"tunes\":{\"textVariant\":\"\"}}],\"version\":\"2.22.2\",\"storage\":0}', '2022-01-21 18:57:08', NULL),
