u0438\\u0439 \\u0441\\u0430\\u043c\\u044b\\u0435 \\u0434\\u0435\\u0442\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u044d\\u043b\\u0435\\u043c\\u0435\\u043d\\u0442\\u044b \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u044b, \\u0430\\u043d\\u0430\\u043b\\u043e\\u0433\\u043e\\u0432 \\u043a\\u043e\\u0442\\u043e\\u0440\\u043e\\u043c\\u0443 \\u043f\\u043e\\u043a\\u0430 \\u043d\\u0435 \\u043f\\u0440\\u0438\\u0434\\u0443\\u043c\\u0430\\u043b\\u0438. AIDA64, \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e, \\u043d\\u0435 \\u0442\\u0435\\u0441\\u0442\\u0435\\u0440 \\u0430\\u043f\\u043f\\u0430\\u0440\\u0430\\u0442\\u043d\\u043e\\u0439 \\u0447\\u0430\\u0441\\u0442\\u0438, \\u0437\\u0430\\u0442\\u043e \\u0441\\u0430\\u043c\\u044b\\u0439 \\u043b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0442\\u043e\\u0440, \\u043f\\u0440\\u0438\\u0448\\u0435\\u0434\\u0448\\u0438\\u0439 \\u043d\\u0430 \\u0437\\u0430\\u043c\\u0435\\u043d\\u0443 Everest.\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"L9sVhnI_1C\",\"type\":\"image\",\"data\":{\"url\":\"\\/data\\/posts\\/a0b812851c8bcf7d5bfa170f4cdc186a\\/L9sVhnI_1C.jpeg\",\"caption\":\"\",\"withBorder\":false,\"withBackground\":false,\"stretched\":false}},{\"id\":\"NrDbIQKZ7h\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\u041a\\u0441\\u0442\\u0430\\u0442\\u0438, \\u0435\\u0449\\u0451 \\u043e\\u0434\\u043d\\u0438\\u043c \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043a\\u043e\\u043c \\u043c\\u043e\\u0436\\u043d\\u043e \\u043d\\u0430\\u0437\\u0432\\u0430\\u0442\\u044c \\u043f\\u0440\\u0438\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0438\\u0435 \\u043a\\u043d\\u043e\\u043f\\u043e\\u043a \\u044f\\u043a\\u043e\\u0431\\u044b \\u0434\\u043b\\u044f \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0434\\u0440\\u0430\\u0439\\u0432\\u0435\\u0440\\u043e\\u0432 \\u0438 BIOS, \\u043f\\u043b\\u044e\\u0441 \\u0435\\u0449\\u0451 \\u043f\\u0440\\u0438\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0430 \\\"\\u043f\\u043e\\u043f\\u0440\\u043e\\u0448\\u0430\\u0439\\u043a\\u0430\\\". \\u0412\\u0441\\u0435 \\u044d\\u0442\\u0438 \\u043f\\u0443\\u043d\\u043a\\u0442\\u044b \\u043d\\u0438\\u043a\\u0430\\u043a \\u0438\\u043d\\u0430\\u0447\\u0435 \\u0432\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u044b \\u0434\\u043b\\u044f \\u0432\\u044b\\u043a\\u0430\\u0447\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u0434\\u0435\\u043d\\u0435\\u0433, \\u043d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 \\u0441\\u043e\\u043c\\u043d\\u0435\\u043d\\u0438\\u0439. \\u0411\\u0443\\u0434\\u0442\\u043e \\u043a\\u043e\\u043c\\u043f\\u0430\\u043d\\u0438\\u0438 \\u0431\\u0438\\u0437\\u043d\\u0435\\u0441-\\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 AIDA64 \\u043d\\u0435 \\u0445\\u0432\\u0430\\u0442\\u0430\\u0435\\u0442.\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"NdeBAhAh21\",\"type\":\"image\",\"data\":{\"url\":\"\\/data\\/posts\\/a0b812851c8bcf7d5bfa170f4cdc186a\\/NdeBAhAh21.jpeg\",\"caption\":\"\",\"withBorder\":false,\"withBackground\":false,\"stretched\":false}},{\"id\":\"nAJPmwyhKP\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\u041a\\u0441\\u0442\\u0430\\u0442\\u0438, \\u043e\\u0449\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435, \\u0447\\u0442\\u043e \\u043f\\u0440\\u0435\\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0435\\u043a\\u0442\\u043e\\u0432 \\u043d\\u0435\\u043c\\u0430\\u043b\\u043e \\u0437\\u0430\\u0434\\u0435\\u043b\\u043e \\u043a\\u0430\\u043a \\u0440\\u0430\\u0437 \\u0431\\u0438\\u0437\\u043d\\u0435\\u0441-\\u0440\\u0435\\u0434\\u0430\\u043a\\u0446\\u0438\\u044e, \\u043a\\u0443\\u0434\\u0430 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u043e \\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u043e \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043e\\u043f\\u0446\\u0438\\u0439, \\u043e \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0445 \\u0443\\u043f\\u043e\\u043c\\u044f\\u043d\\u0443\\u0442\\u043e \\u0432 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0435 \\u043d\\u0430 \\u0441\\u0430\\u0439\\u0442\\u0435 \\u0440\\u0430\\u0437\\u0440\\u0430\\u0431\\u043e\\u0442\\u0447\\u0438\\u043a\\u043e\\u0432. \\u041e\\u0431\\u044b\\u0447\\u043d\\u044b\\u043c \\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f\\u043c \\u043e\\u043d\\u0438 \\u0438 \\u043d\\u0435 \\u043a \\u0447\\u0435\\u043c\\u0443, \\u043d\\u043e \\u043a\\u043e\\u043c\\u0443-\\u0442\\u043e \\u043e\\u0441\\u0442\\u0440\\u043e \\u043d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u0430.\"},\"tunes\":{\"textVariant\":\"\"}},{\"id\":\"Li8Prdf3g3\",\"type\":\"image\",\"data\":{\"url\":\"\\/data\\/posts\\/a0b812851c8bcf7d5bfa170f4cdc186a\\/Li8Prdf3g3.jpeg\",\"caption\":\"\",\"withBorder\":false,\"withBackground\":false,\"stretched\":false}},{\"id\":\"ya71WXg2zp\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\u0412 \\u0437\\u0430\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0438\\u0438, \\u043c\\u043e\\u0433\\u0443 \\u0441\\u043a\\u0430\\u0437\\u0430\\u0442\\u044c, \\u0447\\u0442\\u043e \\u043d\\u043e\\u0432\\u0435\\u043d\\u044c\\u043a\\u0438\\u0439 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0442 \\u043f\\u043e\\u0434 \\u043d\\u0430\\u0437\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c AIDA64 Extreme Edition \\u043d\\u0438\\u043a\\u0430\\u043a \\u043d\\u0435 \\u043c\\u043e\\u0433 \\u0440\\u0430\\u0437\\u043e\\u0447\\u0430\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043c\\u0435\\u043d\\u044f. \\u0414\\u0430, \\u0435\\u0441\\u0442\\u044c \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043a\\u0438, \\u043d\\u043e \\u043e\\u043d\\u0438 \\u043c\\u0435\\u0440\\u043a\\u043d\\u0443\\u0442 \\u043d\\u0430 \\u0444\\u043e\\u043d\\u0435 \\u0443\\u0442\\u0438\\u043b\\u0438\\u0442\\u044b, \\u043d\\u0430 \\u0444\\u043e\\u043d\\u0435 \\u0432\\u0441\\u0435\\u0433\\u043e \\u0435\\u0451 \\u0444\\u0443\\u043d\\u043a\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0430 \\u0438 \\u043f\\u043e\\u0434\\u0440\\u043e\\u0431\\u043d\\u0435\\u0439\\u0448\\u0435\\u0433\\u043e \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430 \\u0432\\u043d\\u0443\\u0442\\u0440\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 \\u041f\\u041a.\"},\"tunes\":{\"textVariant\":\"\"}}],\"version\":\"2.22.2\",\"storage\":0}', '2022-01-21 20:25:24', '2022-01-21 20:44:59');

